from collections import deque


def general_match_max(n, adj):
    """一般图最大匹配（带花树，最简实现 O(VE²)）。
    adj[u]: 邻居列表（无向）。返回 match: match[u] = u 的配偶（-1 未匹配）。"""
    match = [-1] * n
    p = [-1] * n
    base = list(range(n))
    used = [False] * n
    blossom = [False] * n
    q = deque()

    def lca(a, b):
        used_lca = [False] * n
        while True:
            a = base[a]
            used_lca[a] = True
            if match[a] == -1:
                break
            a = p[match[a]]
        while True:
            b = base[b]
            if used_lca[b]:
                return b
            b = p[match[b]]

    def mark_path(v, b, children):
        while base[v] != b:
            blossom[base[v]] = blossom[base[match[v]]] = True
            p[v] = children
            children = match[v]
            v = p[match[v]]

    def find_path(root):
        used[:] = [False] * n
        p[:] = [-1] * n
        for i in range(n):
            base[i] = i
        q = deque([root])
        used[root] = True
        while q:
            v = q.popleft()
            for u in adj[v]:
                if base[v] == base[u] or match[v] == u:
                    continue
                if u == root or (match[u] != -1 and p[match[u]] != -1):
                    curbase = lca(v, u)
                    blossom[:] = [False] * n
                    mark_path(v, curbase, u)
                    mark_path(u, curbase, v)
                    for i in range(n):
                        if blossom[base[i]]:
                            base[i] = curbase
                            if not used[i]:
                                used[i] = True
                                q.append(i)
                elif p[u] == -1:
                    p[u] = v
                    if match[u] == -1:
                        return u
                    u = match[u]
                    used[u] = True
                    q.append(u)
        return -1

    def enlarge(u):
        while u != -1:
            v = p[u]
            nv = match[v]
            match[u], match[v] = v, u
            u = nv

    for i in range(n):
        if match[i] == -1:
            v = find_path(i)
            if v != -1:
                enlarge(v)
    return match


if __name__ == '__main__':
    import random

    def brute_max(n, adj):
        """一般图最大匹配的暴力枚举（每个点至多被匹配一次）"""
        best = 0

        def rec(used_v, cnt):
            nonlocal best
            best = max(best, cnt)
            u = -1
            for i in range(n):
                if not (used_v >> i) & 1:
                    u = i
                    break
            if u == -1:
                return
            rec(used_v | (1 << u), cnt)
            for w in adj[u]:
                if not (used_v >> w) & 1:
                    rec(used_v | (1 << u) | (1 << w), cnt + 1)
        rec(0, 0)
        return best

    random.seed(7)
    for _ in range(150):
        n = random.randint(2, 10)
        adj = [set() for _ in range(n)]
        for i in range(n):
            for j in range(i + 1, n):
                if random.random() < 0.35:
                    adj[i].add(j)
                    adj[j].add(i)
        adj = [list(s) for s in adj]
        mt = general_match_max(n, adj)
        size = sum(1 for i in range(n) if mt[i] != -1 and mt[i] > i)
        assert size == brute_max(n, adj), (n, adj, mt, size, brute_max(n, adj))
    print('general-match: All tests passed.')
